# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs, factor=10):
    return [v * factor for v in xs]

# region: render
def render(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: emit
def emit(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return emit(digest(render(fold(intake(sift(raw))))))

